function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 500) return 'grid needs 1 to 500 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 500) return 'Each row needs 1 to 500 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row must have the same length.';
    if (row.some(cell => cell !== 'W' && cell !== 'E' && cell !== '0')) return "Each cell is 'W', 'E' or '0'.";
  }
  return null;
}

