function maxKilledEnemies(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const colHits = new Array(cols).fill(0);
  let rowHits = 0;
  let best = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (c === 0 || grid[r][c - 1] === 'W') {
        rowHits = 0;
        for (let k = c; k < cols && grid[r][k] !== 'W'; k++) {
          if (grid[r][k] === 'E') {
            rowHits++;
          }
        }
      }
      if (r === 0 || grid[r - 1][c] === 'W') {
        colHits[c] = 0;
        for (let k = r; k < rows && grid[k][c] !== 'W'; k++) {
          if (grid[k][c] === 'E') {
            colHits[c]++;
          }
        }
      }
      if (grid[r][c] === '0') {
        best = Math.max(best, rowHits + colHits[c]);
      }
    }
  }
  return best;
}

