function maxKilledEnemies(grid) {
  // Try every empty cell and walk outward in all four directions until a wall or the edge.
  let best = 0;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[0].length; c++) {
      if (grid[r][c] !== '0') continue;
      let killed = 0;
      for (const [dr, dc] of directions) {
        let y = r + dr, x = c + dc;
        while (y >= 0 && y < grid.length && x >= 0 && x < grid[0].length && grid[y][x] !== 'W') {
          if (grid[y][x] === 'E') killed++;
          y += dr;
          x += dc;
        }
      }
      best = Math.max(best, killed);
    }
  }
  return best;
}

