function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const rows = large ? 100 : 1 + pick(5);
  const cols = large ? 100 : 1 + pick(5);
  // Vary how crowded the grid is with walls and enemies.
  const wallRate = rand() * (large ? 0.3 : 0.5);
  const enemyRate = rand() * 0.6;
  const cells = [];
  for (let r = 0; r < rows; r++) {
    const row = [];
    for (let c = 0; c < cols; c++) {
      const x = rand();
      row.push(x < wallRate ? 'W' : x < wallRate + enemyRate * (1 - wallRate) ? 'E' : '0');
    }
    cells.push(row);
  }
  return [cells];
}
